import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2024-02-01');
  assert.equal(Array.isArray(result), true);
  assert.equal(result.length, 0);
});

test('overdueInvoices excludes invoices with dueDate on or after asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  // dueDate: 2024-01-29

  const result = overdueInvoices([issued], '2024-01-29');
  assert.equal(result.length, 0);

  const result2 = overdueInvoices([issued], '2024-01-30');
  assert.equal(result2.length, 1);
});

test('overdueInvoices includes invoice with dueDate strictly before asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  // dueDate: 2024-01-29

  const result = overdueInvoices([issued], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2024-0001');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  // dueDate: 2024-01-29

  const result = overdueInvoices([issued], '2024-02-05');
  assert.equal(result.length, 1);
  // 2024-01-29 to 2024-02-05 = 7 days
  assert.equal(result[0].daysOverdue, 7);
});

test('overdueInvoices includes issued invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;

  const result = overdueInvoices([issued], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2024-0001');
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  const partial = recordPayment(issued, { amount: 10000, date: '2024-01-20' }).value;

  const result = overdueInvoices([partial], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2024-0001');
});

test('overdueInvoices excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  // Invoice is still in draft (not issued yet)
  const result = overdueInvoices([r.value], '2024-02-01');
  assert.equal(result.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  const paid = recordPayment(issued, { amount: 51425, date: '2024-01-20' }).value;

  const result = overdueInvoices([paid], '2024-02-01');
  assert.equal(result.length, 0);
});

test('overdueInvoices calculates due amount correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  const partial = recordPayment(issued, { amount: 20000, date: '2024-01-20' }).value;
  // Total: 51425, Paid: 20000, Due: 31425

  const result = overdueInvoices([partial], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 31425);
});

test('overdueInvoices for fully paid invoice shows due of 0 but still excluded', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  const paid = recordPayment(issued, { amount: 51425, date: '2024-01-20' }).value;

  const result = overdueInvoices([paid], '2024-02-01');
  assert.equal(result.length, 0);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  // Invoice 1: issued 2024-01-15, due 2024-01-29
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  // Invoice 2: issued 2024-01-01, due 2024-01-15
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  // Invoice 3: issued 2024-01-10, due 2024-01-24
  const r3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-10',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued1 = issueInvoice(r1.value, []).value;
  const issued2 = issueInvoice(r2.value, ['INV-2024-0001']).value;
  const issued3 = issueInvoice(r3.value, ['INV-2024-0001', 'INV-2024-0002']).value;

  const invoices = [issued1, issued2, issued3];

  const result = overdueInvoices(invoices, '2024-02-10');
  assert.equal(result.length, 3);

  // Most overdue first
  // Invoice 2: due 2024-01-15, overdue by 26 days
  // Invoice 3: due 2024-01-24, overdue by 17 days
  // Invoice 1: due 2024-01-29, overdue by 12 days
  assert.equal(result[0].number, 'INV-2024-0002');
  assert.equal(result[0].daysOverdue, 26);
  assert.equal(result[1].number, 'INV-2024-0003');
  assert.equal(result[1].daysOverdue, 17);
  assert.equal(result[2].number, 'INV-2024-0001');
  assert.equal(result[2].daysOverdue, 12);
});

test('overdueInvoices includes customer ID', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;

  const result = overdueInvoices([issued], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].customerId, 'C-002');
});

test('overdueInvoices with multiple invoices from same customer', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DES-HOUR', qty: 3, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued1 = issueInvoice(r1.value, []).value;
  const issued2 = issueInvoice(r2.value, ['INV-2024-0001']).value;

  const result = overdueInvoices([issued1, issued2], '2024-02-10');
  assert.equal(result.length, 2);
  assert.equal(result[0].customerId, 'C-001');
  assert.equal(result[1].customerId, 'C-001');
});

test('overdueInvoices with no dueDate returns empty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
    // No terms, so no dueDate
  });

  const issued = issueInvoice(r.value, []).value;

  // Remove dueDate to simulate missing data
  const invoiceWithoutDueDate = { ...issued, dueDate: undefined };

  const result = overdueInvoices([invoiceWithoutDueDate], '2024-02-01');
  assert.equal(result.length, 0);
});

test('overdueInvoices 1 day overdue', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  // dueDate: 2024-01-29

  const result = overdueInvoices([issued], '2024-01-30');
  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices many days overdue', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  // dueDate: 2024-01-29

  const result = overdueInvoices([issued], '2024-04-15');
  assert.equal(result.length, 1);
  // 2024-01-29 to 2024-04-15 = 78 days
  assert.equal(result[0].daysOverdue, 78);
});

test('overdueInvoices with EOM terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'EOM'
  });

  const issued = issueInvoice(r.value, []).value;
  // dueDate: 2024-01-31 (end of month)

  const result = overdueInvoices([issued], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].dueDate, '2024-01-31');
  assert.equal(result[0].daysOverdue, 1);
});

test('overdueInvoices with invoice that has discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
    terms: 'NET14'
  });

  const issued = issueInvoice(r.value, []).value;
  const partial = recordPayment(issued, { amount: 5000, date: '2024-01-20' }).value;
  // Subtotal: 42500, Discount: 4250, VAT: 8032, Total: 46282
  // Paid: 5000, Due: 41282

  const result = overdueInvoices([partial], '2024-02-01');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, 41282);
});

test('overdueInvoices across multiple years', () => {
  // Invoice in 2023
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  // Invoice in 2024
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued1 = issueInvoice(r1.value, []).value;
  const issued2 = issueInvoice(r2.value, ['INV-2023-0001']).value;

  const result = overdueInvoices([issued1, issued2], '2024-02-01');
  assert.equal(result.length, 2);

  // 2023 invoice should be more overdue
  assert.equal(result[0].number, 'INV-2023-0001');
  assert.equal(result[1].number, 'INV-2024-0001');
});

test('overdueInvoices with NET30 terms', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
    // Default terms is NET30
  });

  const issued = issueInvoice(r.value, []).value;
  // dueDate: 2024-02-14 (30 days later)

  const result = overdueInvoices([issued], '2024-02-20');
  assert.equal(result.length, 1);
  assert.equal(result[0].dueDate, '2024-02-14');
  assert.equal(result[0].daysOverdue, 6);
});

