  assert.equal(result[0].daysOverdue, 26);
  assert.equal(result[1].number, 'INV-2024-0003');
  assert.equal(result[1].daysOverdue, 17);
  assert.equal(result[2].number, 'INV-2024-0001');
  assert.equal(result[2].daysOverdue, 12);
});

