test('overdueInvoices sorts by daysOverdue descending', () => {
  // Invoice 1: issued 2024-01-15, due 2024-01-29
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  // Invoice 2: issued 2024-01-01, due 2024-01-15
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  // Invoice 3: issued 2024-01-10, due 2024-01-24
  const r3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-10',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    terms: 'NET14'
  });

  const issued1 = issueInvoice(r1.value, []).value;
  const issued2 = issueInvoice(r2.value, ['INV-2024-0001']).value;
  const issued3 = issueInvoice(r3.value, ['INV-2024-0001', 'INV-2024-0002']).value;

  const invoices = [issued1, issued2, issued3];

  const result = overdueInvoices(invoices, '2024-02-10');
  assert.equal(result.length, 3);

  // Most overdue first
  // Invoice 2: due 2024-01-15, overdue by 26 days
  // Invoice 3: due 2024-01-24, overdue by 17 days
  // Invoice 1: due 2024-01-29, overdue by 12 days
  assert.equal(result[0].number, 'INV-2024-0002');
  assert.equal(result[0].daysOverdue, 26);
  assert.equal(result[1].number, 'INV-2024-0003');
  assert.equal(result[1].daysOverdue, 17);
  assert.equal(result[2].number, 'INV-2024-0001');
  assert.equal(result[2].daysOverdue, 12);
});

